import { live, serialize } from './model.js';
import { esc } from './ui.js';
import { APP_VERSION } from './version.js';
import { utf8Bytes } from './limits.js';
export function settingsView({ state, ssh, token, syncing, diagnostic, backupStatus }) {
  const c = state.config;
  return `<div class="settings">${ssh ? `<section class="panel"><div class="panel-header"><h2>本机 SSH 同步</h2><span class="badge blue">无需令牌</span></div><div class="panel-body"><p>使用这台电脑已有的 SSH key，同步到 ${esc(c.owner)}/${esc(c.repo)}。</p><p>数据文件：${esc(c.path)}</p><button class="primary" data-action="sync" ${syncing ? 'disabled' : ''}>${syncing ? '同步中…' : '立即通过 SSH 同步'}</button><p class="section-gap">私钥始终留在本机。手机或公开网页可使用下面的令牌方式连接同一份数据。</p>${state.pending ? '<button class="secondary" data-action="resolve-pending">处理同步冲突</button>' : ''}</div></section><details><summary>其他仓库或令牌方式</summary>` : ''}<section class="panel"><div class="panel-header"><h2>GitHub 私有同步</h2></div><div class="panel-body"><p>每台设备先保存在本地，点击“立即同步”合并云端记录。专用令牌只在当前页面会话中使用，关闭或刷新页面后需要重新填写。</p><form id="settings-form" class="form-stack"><div class="form-grid"><label>GitHub 用户名<input name="owner" value="${esc(c.owner)}" required></label><label>私有仓库名<input name="repo" value="${esc(c.repo)}" required></label><label class="span-2">数据文件路径<input name="path" value="${esc(c.path)}" required></label><label class="span-2">本次会话的访问令牌<input name="token" type="password" autocomplete="off" spellcheck="false" placeholder="Fine-grained personal access token" value="${esc(token)}"></label></div><div><button class="primary" type="submit" ${syncing ? 'disabled' : ''}>保存连接设置</button> <button class="secondary" data-action="sync" type="button" ${syncing ? 'disabled' : ''}>立即同步</button></div><small>令牌选择此数据仓库，Contents 权限设置为 Read and write。只接受私有仓库，不会上传到公开仓库。</small></form><div class="button-row"><a href="https://github.com/settings/personal-access-tokens" target="_blank" rel="noopener noreferrer">创建专用令牌 ↗</a><button class="text-button" data-action="forget-token">清除当前令牌</button></div>${state.pending ? '<div class="button-row warning">存在尚未处理的冲突。<button class="text-button" data-action="resolve-pending">处理冲突</button></div>' : ''}</div></section>${ssh ? '</details>' : ''}<section class="panel"><div class="panel-header"><h2>导入、备份与导出</h2></div><div class="panel-body"><p>完整 JSON 备份包含记录、同步基线、未解决冲突及本机草稿。Markdown 适合放回 Obsidian 阅读。</p><div class="button-row"><button class="secondary" data-action="choose-file">导入 Markdown / JSON</button><button class="secondary" data-action="export-json">导出完整备份</button><button class="secondary" data-action="snapshots">本机快照</button><button class="secondary" data-action="export-md">导出 Markdown</button></div><p class="section-gap">已导入 ${live(state.data.imports).length} 个批次。原文内容保留在私有数据中。</p><small>本机自动保留最近 20 个操作快照；清理网站数据会同时清除快照。请下载完整备份并单独保存。</small></div></section>${['localhost', '127.0.0.1'].includes(location.hostname) ? `<section class="panel"><div class="panel-header"><h2>浏览器之外的自动备份</h2></div><div class="panel-body"><p>工作台打开时，保存记录或草稿后会自动写入本机私有目录 .local/backups/；每个来源保留最近30个有备份日期的首份及最新一份。</p><p id="disk-backup-status" role="status">${esc(backupStatus?.message || '正在检查…')}</p><div class="button-row"><button class="secondary" data-action="backup-now">立即备份</button><button class="secondary" data-action="disk-backups">查看独立备份</button></div><small>关闭页面前最后几秒的输入可能尚未写入磁盘，下次打开会补备份。磁盘备份仍在这台电脑上。</small></div></section>` : ''}<section class="panel"><div class="panel-header"><h2>版本与连接检查</h2><span class="badge">v${APP_VERSION}</span></div><div class="panel-body"><p>最近同步：${esc(state.lastSync ? new Date(state.lastSync).toLocaleString('zh-CN') : '尚未同步')}</p><p>数据文件：${(utf8Bytes(serialize(state.data)) / 1000).toFixed(1)} KB / 5 MB</p><button class="secondary" data-action="diagnose" ${syncing ? 'disabled' : ''}>检查连接</button><p id="diagnostic-result" class="section-gap" role="status">${esc(diagnostic || '检查只读取连接和云端文件，不上传记录。')}</p></div></section></div>`;
}
